export default function App(){
  const [screen,setScreen]=useState('login');
  const [menu,setMenu]=useState(initialMenu);
  const [editing,setEditing]=useState(null);
  const [form,setForm]=useState(emptyDish);
  const [preview,setPreview]=useState(null);
  const [stock,setStock]=useState(initialInventory);
  const [orders,setOrders]=useState(initialOrders);
  const [recipes,setRecipes]=useState(initialRecipes);
  const [staff,setStaff]=useState(initialStaff);
  const [staffTasks,setStaffTasks]=useState(initialStaffTasks);
  const [checks,setChecks]=useState(initialChecks);
  const [costs,setCosts]=useState({});
  const [allergyNote,setAllergyNote]=useState('Ask every guest about allergies. Common risks include nuts, dairy, eggs, gluten, shellfish, sesame and soy.');
  const [expenses,setExpenses]=useState(initialExpenses);
  const go=(next)=>setScreen(next);
  const logout=()=>setScreen('farewell');
  const openNew=()=>{setEditing(null);setForm(emptyDish);setScreen('editor');};
  const openEdit=(dish)=>{setEditing(dish);setForm({...dish});setScreen('editor');};
  const save=()=>{
    if(!form.name.trim()||!form.price.trim()) return Alert.alert('Name and price required','Add the dish name and price before saving.');
    const price=Number(String(form.price).replace(',','.'));
    if(!Number.isFinite(price)||price<=0) return Alert.alert('Check the price','Enter a valid price greater than zero.');
    const dish={...form,name:form.name.trim(),price:price.toFixed(2),id:editing?.id||Date.now().toString(),image:form.image||food.margherita};
    const wasEditing=Boolean(editing);
    setMenu(items=>wasEditing?items.map(x=>x.id===editing.id?dish:x):[dish,...items]);
    setScreen('menu');
    Alert.alert(wasEditing?'Menu item updated':'Menu item added',`${dish.name} is now reflected in your menu.`);
  };
  const remove=()=>Alert.alert('Delete menu item?',`Remove ${editing.name} from the menu?`,[
    {text:'Cancel',style:'cancel'},
    {text:'Delete',style:'destructive',onPress:()=>{setMenu(items=>items.filter(x=>x.id!==editing.id));setScreen('menu');Alert.alert('Menu item deleted',`${editing.name} has been removed.`);}}
  ]);
  if(screen==='login') return <Login onLogin={()=>go('home')}/>;
  if(screen==='farewell') return <Farewell onReturn={()=>go('login')}/>;
  if(screen==='home') return <Home go={go} logout={logout}/>;
  if(screen==='search') return <GlobalSearch menu={menu} staff={staff} go={go} logout={logout} openEdit={openEdit}/>;
  if(screen==='mainOptions') return <MainOptions go={go} logout={logout}/>;
  if(screen==='menuOptions') return <OptionsPage type="menu" go={go} logout={logout}/>;
  if(screen==='restaurantOptions') return <OptionsPage type="restaurant" go={go} logout={logout}/>;
  if(screen==='menu') return <MenuManager menu={menu} go={go} logout={logout} openNew={openNew} openEdit={openEdit} preview={preview} setPreview={setPreview}/>;
  if(screen==='itemCustomization') return <ItemCustomization menu={menu} go={go} logout={logout} openNew={openNew} openEdit={openEdit}/>;
  if(screen==='menuPreview') return <MenuPreviewScreen menu={menu} go={go} logout={logout}/>;
  if(screen==='dishPreview') return <DishPreviewScreen menu={menu} go={go} logout={logout} openEdit={openEdit}/>;
  if(screen==='editor') return <Editor form={form} setForm={setForm} onSave={save} onDelete={editing?remove:null} onBack={()=>go('menu')} onOptions={()=>go('menuOptions')} onSearch={()=>go('search')} logout={logout}/>;
  if(screen==='restaurant') return <RestaurantHub go={go} logout={logout}/>;
  if(screen==='inventory') return <Inventory stock={stock} setStock={setStock} go={go} logout={logout}/>;
  if(screen==='orders') return <Orders orders={orders} setOrders={setOrders} staff={staff} go={go} logout={logout}/>;
  if(screen==='analytics') return <Analytics expenses={expenses} setExpenses={setExpenses} go={go} logout={logout}/>;
  if(screen==='recipes') return <Recipes recipes={recipes} setRecipes={setRecipes} go={go} logout={logout}/>;
  if(screen==='costs') return <FoodCosts menu={menu} costs={costs} setCosts={setCosts} go={go} logout={logout}/>;
  if(screen==='staff') return <Staff staff={staff} setStaff={setStaff} tasks={staffTasks} setTasks={setStaffTasks} go={go} logout={logout}/>;
  if(screen==='safety') return <Safety checks={checks} setChecks={setChecks} allergy={allergyNote} setAllergy={setAllergyNote} go={go} logout={logout}/>;
  return <Home go={go} logout={logout}/>;
}

function Header({section='Chef control panel',onBack,logout,onOptions,onSearch}){
  return <View style={s.header}><View style={s.utility}>{logout?<Pressable onPress={logout} hitSlop={10} style={({pressed})=>[s.utilityButton,pressed&&s.utilityButtonPressed]}><Text style={s.utilityText}>LOGOUT</Text></Pressable>:<View style={s.utilityButton}/>}<Text style={s.utilityBrand}>CRISTOFELL PIZZARIA</Text>{onOptions?<Pressable onPress={onOptions} hitSlop={10} style={({pressed})=>[s.utilityButton,pressed&&s.utilityButtonPressed]}><Text style={s.utilityText}>OPTIONS</Text></Pressable>:<View style={s.utilityButton}/>}</View><View style={s.headerMain}>{onBack&&<Pressable onPress={onBack} hitSlop={8} style={s.back}><Text style={s.backText}>‹</Text></Pressable>}<View style={s.headerBrand}><Image source={LOGO} style={s.headerLogo} resizeMode="contain"/><Text style={s.section}>{section}</Text></View><Pressable onPress={onSearch} disabled={!onSearch} style={({pressed})=>[s.search,pressed&&onSearch&&s.searchPressed]}><Text style={s.searchIcon}>⌕</Text><Text style={s.searchLabel}>{onSearch?'SEARCH':'SEARCH'}</Text></Pressable></View></View>;
}
function Login({onLogin}){const [email,setEmail]=useState('');const [pass,setPass]=useState('');const [errors,setErrors]=useState({});const submit=()=>{const next={};const cleanEmail=email.trim();if(!cleanEmail)next.email='Your email address is required.';else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanEmail))next.email='Enter a valid email address.';if(!pass)next.pass='Your password is required.';else if(pass.length<6)next.pass='Password must contain at least 6 characters.';setErrors(next);if(Object.keys(next).length)return Alert.alert('Login details needed',next.email||next.pass);onLogin();};return <SafeAreaView style={s.loginSafe}><StatusBar barStyle="light-content"/><Image source={LOGIN_PIZZA} style={s.loginBackground} resizeMode="cover"/><View style={s.loginOverlay}/><ScrollView contentContainerStyle={s.login} keyboardShouldPersistTaps="handled"><Text style={s.welcome}>WELCOME TO</Text><Image source={LOGO} style={s.loginLogo} resizeMode="contain"/><Text style={s.loginSub}>Christofell, I’m ready to help you manage today’s service.</Text><View style={s.loginForm}><TextInput value={email} onChangeText={value=>{setEmail(value);if(errors.email)setErrors({...errors,email:null});}} style={[s.loginInput,errors.email&&s.loginInputError]} placeholder="EMAIL ADDRESS" placeholderTextColor="#6b625d" autoCapitalize="none" autoCorrect={false} keyboardType="email-address" autoComplete="email" textContentType="emailAddress" returnKeyType="next"/>{errors.email&&<Text style={s.loginError}>{errors.email}</Text>}<TextInput value={pass} onChangeText={value=>{setPass(value);if(errors.pass)setErrors({...errors,pass:null});}} style={[s.loginInput,errors.pass&&s.loginInputError]} placeholder="PASSWORD" placeholderTextColor="#6b625d" secureTextEntry autoComplete="password" textContentType="password" returnKeyType="done" onSubmitEditing={submit}/>{errors.pass&&<Text style={s.loginError}>{errors.pass}</Text>}<Pressable onPress={submit} style={s.loginButton}><Text style={s.loginButtonText}>LOGIN</Text></Pressable><Text style={s.demo}>Use a valid email and a password of at least 6 characters.</Text></View></ScrollView></SafeAreaView>}
function Farewell({onReturn}){return <SafeAreaView style={s.farewellSafe}><StatusBar barStyle="light-content"/><View style={s.farewell}><Image source={{uri:food.hero}} style={s.farewellImage}/><View style={s.farewellShade}/><View style={s.farewellContent}><Text style={s.farewellKicker}>SERVICE COMPLETE</Text><Image source={LOGO} style={s.farewellBrandLogo} resizeMode="contain"/><View style={s.farewellRule}/><Text style={s.farewellTitle}>Thank you, Christofell.</Text><Text style={s.farewellCopy}>I’ve ended your session safely. Great food brings people together, and I’ll be ready for your next service.</Text><Pressable onPress={onReturn} style={s.returnButton}><Text style={s.returnButtonText}>RETURN TO LOGIN</Text></Pressable></View></View></SafeAreaView>}
function Home({go,logout}){return <SafeAreaView style={s.safe}><Header logout={logout} onOptions={()=>go('mainOptions')} onSearch={()=>go('search')}/><ScrollView style={{backgroundColor:BLUE}}><View style={s.homeHero}><Text style={s.homeTitle}>Chef's dashboard</Text><Text style={s.homeCopy}>Christofell, I’ve brought everything you need for today’s service into one place.</Text></View><Image source={{uri:food.hero}} style={s.homeImage}/><View style={s.homeBody}><Text style={s.chefGreeting}>Hi Chef Christofell, what would you like to review today?</Text><BigChoice title="Menu management" copy="I’ll help you build dishes, set pricing and preview your diner menu." accent={ORANGE} onPress={()=>go('menu')}/><BigChoice title="Restaurant management" copy="I’ll help you track orders, stock, staff and sales performance." accent={BLUE} onPress={()=>go('restaurant')}/></View></ScrollView></SafeAreaView>}
function MainOptions({go,logout}){return <SafeAreaView style={s.safe}><Header section="Application options" logout={logout} onBack={()=>go('home')} onSearch={()=>go('search')}/><ScrollView style={{backgroundColor:BLUE}} contentContainerStyle={s.mainOptions}><Text style={s.blueTitle}>Choose an options area</Text><Text style={s.blueCopy}>Christofell, I’ve organised every tool so you can move around your restaurant quickly.</Text><BigChoice title="Menu options" copy="I’ll take you to menu customization, item editing and previews." accent={ORANGE} onPress={()=>go('menuOptions')}/><BigChoice title="Restaurant options" copy="I’ll take you to orders, recipes, stock, staff, sales and safety." accent={BLUE} onPress={()=>go('restaurantOptions')}/></ScrollView></SafeAreaView>}
function BigChoice({title,copy,accent,onPress}){return <Pressable onPress={onPress} style={s.bigChoice}><View style={[s.choiceStripe,{backgroundColor:accent}]}/><View style={{flex:1}}><Text style={s.choiceTitle}>{title}</Text><Text style={s.choiceCopy}>{copy}</Text></View><Text style={[s.arrow,{color:accent}]}>→</Text></Pressable>}

function GlobalSearch({menu,staff,go,logout,openEdit}){const [query,setQuery]=useState('');const q=query.trim().toLowerCase();const score=(primary,secondary)=>{const a=primary.toLowerCase();const b=secondary.toLowerCase();if(!q)return 0;if(a===q)return 100;if(a.startsWith(q))return 80;if(a.includes(q))return 60;if(b.includes(q))return 35;return 0;};const dishes=menu.map(item=>({...item,_score:score(item.name,`${item.course} ${item.description} ${item.ingredients} ${item.price}`)})).filter(x=>x._score>0).sort((a,b)=>b._score-a._score);const people=staff.map(person=>({...person,_score:score(person.name,`${person.role} ${person.status}`)})).filter(x=>x._score>0).sort((a,b)=>b._score-a._score);const hasResults=dishes.length||people.length;return <SafeAreaView style={s.safe}><Header section="Global search" logout={logout} onBack={()=>go('home')}/><ScrollView style={{backgroundColor:'#f2f3f7'}} contentContainerStyle={s.globalSearchPage} keyboardShouldPersistTaps="handled"><Text style={s.globalSearchTitle}>What are you looking for, Christofell?</Text><Text style={s.globalSearchCopy}>I can find any dish by its name, course, ingredient or description, and any staff member by name, role or attendance.</Text><View style={s.globalSearchBox}><Text style={s.globalSearchIcon}>⌕</Text><TextInput value={query} onChangeText={setQuery} autoFocus placeholder="Try ‘chicken’, ‘dessert’ or ‘assistant chef’" style={s.globalSearchInput} returnKeyType="search"/><Pressable onPress={()=>setQuery('')}><Text style={s.searchClear}>{query?'×':''}</Text></Pressable></View>{!q&&<View style={s.searchTips}><Text style={s.searchTipsTitle}>QUICK SEARCHES</Text><View style={s.searchTipRow}>{['pizza','starter','milkshake','chef','present'].map(term=><Pressable key={term} onPress={()=>setQuery(term)} style={s.searchTip}><Text style={s.searchTipText}>{term}</Text></Pressable>)}</View></View>}{q&&<><Text style={s.resultCount}>{dishes.length+people.length} result{dishes.length+people.length===1?'':'s'} for “{query}”</Text>{dishes.length>0&&<><Text style={s.resultHeading}>DISHES</Text>{dishes.map(dish=><View key={dish.id} style={s.searchResult}><Image source={{uri:dish.image}} style={s.searchResultImage}/><View style={{flex:1}}><Text style={s.searchResultName}>{dish.name}</Text><Text style={s.searchResultMeta}>{dish.course} · R{dish.price}</Text><Text style={s.searchResultDescription} numberOfLines={2}>{dish.description}</Text></View><Pressable onPress={()=>openEdit(dish)} style={s.resultAction}><Text style={s.resultActionText}>EDIT</Text></Pressable></View>)}</>}{people.length>0&&<><Text style={s.resultHeading}>STAFF</Text>{people.map(person=><Pressable key={person.id} onPress={()=>go('staff')} style={s.searchResult}><Image source={{uri:person.image}} style={[s.searchStaffPhoto,{borderColor:person.color}]}/><View style={{flex:1}}><Text style={s.searchResultName}>{person.name}</Text><Text style={s.searchResultMeta}>{person.role} · {person.status}</Text></View><Text style={s.resultArrow}>→</Text></Pressable>)}</>}{!hasResults&&<View style={s.noResults}><Text style={s.noResultsTitle}>I couldn’t find that yet.</Text><Text style={s.noResultsCopy}>Try part of a name, an ingredient, a menu course or a staff role.</Text></View>}</>}</ScrollView></SafeAreaView>}

function MenuManager({menu,go,logout,openNew,openEdit,preview,setPreview}){const [course,setCourse]=useState('All');const [query,setQuery]=useState('');const normalizedQuery=query.trim().toLowerCase();const dishes=useMemo(()=>menu.filter(item=>(course==='All'||item.course===course)&&item.name.toLowerCase().includes(normalizedQuery)),[menu,course,normalizedQuery]);const clearFilters=()=>{setQuery('');setCourse('All');};return <SafeAreaView style={s.safe}><Header section="Menu management" logout={logout} onBack={()=>go('home')} onOptions={()=>go('menuOptions')} onSearch={()=>go('search')}/><ScrollView style={{backgroundColor:ORANGE}} contentContainerStyle={s.pagePad} keyboardShouldPersistTaps="handled"><View style={s.orangeIntro}><Text style={s.eyebrow}>MENU FIRST</Text><Text style={s.pageTitle}>Restaurant Menu Manager</Text><Text style={s.pageCopy}>Christofell, I’ll help you keep your menu fresh, accurate and ready for service.</Text></View><MenuStatistics menu={menu}/><View style={s.searchFilterRow}><TextInput value={query} onChangeText={setQuery} style={[s.inlineSearch,{flex:1}]} placeholder="Search menu items by name…" returnKeyType="search"/>{(query||course!=='All')&&<Pressable onPress={clearFilters} style={s.clearFilter}><Text style={s.clearFilterText}>CLEAR</Text></Pressable>}</View><MenuCourseSelector selected={course} onSelect={setCourse}/><View style={s.listHeader}><View><Text style={s.listTitle}>{course==='All'?'All menu items':course}</Text><Text style={s.muted}>{dishes.length} menu {dishes.length===1?'item':'items'}</Text></View><Pressable onPress={openNew} style={s.add}><Text style={s.addText}>＋ Add item</Text></Pressable></View>{dishes.map(d=><DishCard key={d.id} dish={d} onEdit={()=>openEdit(d)} onPreview={()=>setPreview(d)}/>)}{!dishes.length&&<View style={s.empty}><Text style={s.emptyTitle}>No dishes found</Text><Text style={s.muted}>Christofell, I couldn’t find a matching dish. Clear the search or try another name.</Text></View>}<Pressable onPress={()=>setPreview({all:true,menu})} style={s.fullPreview}><Text style={s.fullPreviewText}>PREVIEW FULL MENU</Text></Pressable></ScrollView><Preview data={preview} close={()=>setPreview(null)}/></SafeAreaView>}
function MenuStatistics({menu}){const average=menu.length?menu.reduce((total,item)=>total+(Number(item.price)||0),0)/menu.length:0;return <View style={s.menuStats}><Text style={s.menuStatsTitle}>Your menu at a glance</Text><View style={s.menuStatsTop}><View style={s.menuStatCard}><Text style={s.menuStatValue}>{menu.length}</Text><Text style={s.menuStatLabel}>TOTAL ITEMS</Text></View><View style={s.menuStatCard}><Text style={s.menuStatValue}>R{average.toFixed(2)}</Text><Text style={s.menuStatLabel}>AVERAGE PRICE</Text></View></View><View style={s.courseStats}>{courses.map(course=><View key={course} style={s.courseStat}><Text style={s.courseStatCount}>{menu.filter(item=>item.course===course).length}</Text><Text style={s.courseStatLabel}>{course==='Main'?'Main Course':course.replace('Desserts','Dessert')}</Text></View>)}</View></View>}
function MenuCourseSelector({selected,onSelect}){const ordered=['All','Starters','Main','Desserts','Drinks'];return <View style={s.courseSelector}><Text style={s.courseSelectorTitle}>Menu Course</Text>{ordered.map(course=><Pressable key={course} onPress={()=>onSelect(course)} style={[s.designedCourse,selected===course&&s.designedCourseActive]}><Text style={s.designedCourseText}>{course==='All'?'All courses':course.replace('Desserts','Dessert')}</Text></Pressable>)}</View>}
function DishCard({dish,onEdit,onPreview}){return <View style={s.dishCard}><Image source={{uri:dish.image}} style={s.dishImage}/><View style={s.dishInfo}><View style={s.dishTop}><Text style={s.dishName}>{dish.name}</Text><Text style={s.dishPrice}>R{dish.price}</Text></View><Text style={s.dishDesc} numberOfLines={3}>{dish.description}</Text><Text style={s.ingredients} numberOfLines={2}>{dish.ingredients}</Text><View style={s.cardActions}><Pressable onPress={onPreview}><Text style={s.textAction}>Preview</Text></Pressable><Pressable onPress={onEdit} style={s.smallEdit}><Text style={s.smallEditText}>Edit item</Text></Pressable></View></View></View>}

function Editor({form,setForm,onSave,onDelete,onBack,onOptions,onSearch,logout}){const field=(key,val)=>setForm({...form,[key]:val});return <SafeAreaView style={s.safe}><Header section={onDelete?'Edit menu item':'Add menu item'} onBack={onBack} onOptions={onOptions} onSearch={onSearch} logout={logout}/><ScrollView style={{backgroundColor:ORANGE}} contentContainerStyle={s.form}><Text style={s.formTitle}>{onDelete?'Update this dish':'Create a delicious new dish'}</Text><Text style={s.formCopy}>Christofell, I’ll use these details to build your menu preview exactly as your diners will see it.</Text><Text style={s.label}>COURSE</Text><View style={s.courseTabs}>{courses.map(x=><Pressable key={x} onPress={()=>field('course',x)} style={[s.courseTab,form.course===x&&s.activeCourse]}><Text style={[s.courseTabText,form.course===x&&{color:'#fff'}]}>{x}</Text></Pressable>)}</View><Field label="DISH NAME" value={form.name} onChangeText={v=>field('name',v)} placeholder="e.g. Margherita Pizza"/><Field label="PRICE (R)" value={form.price} onChangeText={v=>field('price',v)} placeholder="90.00" keyboardType="decimal-pad"/><Field label="DESCRIPTION" value={form.description} onChangeText={v=>field('description',v)} placeholder="Describe the flavour, texture and preparation" multiline/><Field label="INGREDIENTS" value={form.ingredients} onChangeText={v=>field('ingredients',v)} placeholder="Separate ingredients with commas" multiline/><Field label="FOOD PHOTO URL" value={form.image} onChangeText={v=>field('image',v)} placeholder="https://…"/><Pressable onPress={onSave} style={s.saveButton}><Text style={s.saveText}>{onDelete?'SAVE CHANGES':'ADD TO MENU'}</Text></Pressable>{onDelete&&<Pressable onPress={onDelete} style={s.delete}><Text style={s.deleteText}>REMOVE MENU ITEM</Text></Pressable>}</ScrollView></SafeAreaView>}
function Field({label,multiline,...props}){return <View><Text style={s.label}>{label}</Text><TextInput {...props} multiline={multiline} style={[s.field,multiline&&s.textarea]}/></View>}

function RestaurantHub({go,logout}){const tiles=[['Orders','I’ll show you the live kitchen queue.','orders'],['Inventory','I’ll help you review stock levels and costs.','inventory'],['Sales analytics','I’ll show you revenue and top sellers.','analytics'],['Staff','I’ll help you review attendance and weekly tasks.','staff']];return <SafeAreaView style={s.safe}><Header section="Restaurant management" logout={logout} onBack={()=>go('home')} onOptions={()=>go('restaurantOptions')} onSearch={()=>go('search')}/><ScrollView style={{backgroundColor:BLUE}} contentContainerStyle={s.bluePad}><Text style={s.blueTitle}>Restaurant control panel</Text><Text style={s.blueCopy}>Christofell, I’ve prepared a clear view of today’s service for you.</Text><View style={s.metrics}><Metric value="48" label="Orders today"/><Metric value="R 2,379" label="Revenue"/><Metric value="6" label="Low stock"/></View>{tiles.map(([a,b,c])=><Pressable key={a} onPress={()=>go(c)} style={s.hubTile}><View><Text style={s.hubTitle}>{a}</Text><Text style={s.muted}>{b}</Text></View><Text style={s.tileArrow}>→</Text></Pressable>)}</ScrollView></SafeAreaView>}

function OptionsPage({type,go,logout}){
  const menu=type==='menu';
  const items=menu
    ? [['Menu customization','menu'],['Item customization','itemCustomization'],['Menu preview','menuPreview'],['Dish preview','dishPreview']]
    : [['Dish ordering system','orders'],['Recipe management','recipes'],['Inventory management','inventory'],['Food cost management','costs'],['Staff management','staff'],['Sales performance','analytics'],['Health and safety','safety']];
  const color=menu?ORANGE:BLUE;
  return <SafeAreaView style={s.safe}><Header section={`${menu?'Menu':'Restaurant'} management`} logout={logout} onBack={()=>go(menu?'menu':'restaurant')} onSearch={()=>go('search')}/><View style={[s.optionsPage,{backgroundColor:color}]}><Text style={s.optionsEyebrow}>PAGE OPTIONS</Text><Text style={s.optionsTitle}>{menu?'Menu management':'Restaurant management'}</Text><Text style={s.optionsCopy}>{menu?'Christofell, I’ll take you wherever you need to work on your menu.':'Christofell, I’ve placed every restaurant tool here so you can choose what to review.'}</Text><View style={s.optionsCard}><Text style={s.optionsCardTitle}>OPTIONS</Text>{items.map(([label,target])=><Pressable key={label} onPress={()=>go(target)} style={[s.optionRow,{borderLeftColor:color}]}><Text style={s.optionLabel}>{label}</Text><Text style={[s.optionArrow,{color}]}>→</Text></Pressable>)}</View></View></SafeAreaView>
}
function ItemCustomization({menu,go,logout,openNew,openEdit}){return <SafeAreaView style={s.safe}><Header section="Item customization" logout={logout} onBack={()=>go('menuOptions')} onOptions={()=>go('menuOptions')} onSearch={()=>go('search')}/><ScrollView style={{backgroundColor:ORANGE}} contentContainerStyle={s.pagePad}><View style={s.sectionAction}><View style={{flex:1}}><Text style={s.pageTitle}>Customize items</Text><Text style={s.pageCopy}>Christofell, I’ve grouped every dish by course so you can edit it quickly.</Text></View><Pressable onPress={openNew} style={s.add}><Text style={s.addText}>＋ ADD</Text></Pressable></View>{courses.map(course=><View key={course}><Text style={s.customCourseTitle}>{course}</Text>{menu.filter(x=>x.course===course).map(dish=><View key={dish.id} style={s.customItemRow}><Image source={{uri:dish.image}} style={s.customItemImage}/><View style={{flex:1}}><Text style={s.stockName}>{dish.name}</Text><Text style={s.muted}>R{dish.price} · {dish.ingredients}</Text></View><Pressable onPress={()=>openEdit(dish)} style={s.smallEdit}><Text style={s.smallEditText}>EDIT</Text></Pressable></View>)}</View>)}</ScrollView></SafeAreaView>}
function MenuPreviewScreen({menu,go,logout}){return <SafeAreaView style={s.safe}><Header section="Menu preview" logout={logout} onBack={()=>go('menuOptions')} onOptions={()=>go('menuOptions')} onSearch={()=>go('search')}/><View style={s.personalBanner}><Text style={s.personalBannerText}>Christofell, I’ve prepared your customer menu below so you can review it before service.</Text></View><ScrollView style={s.printMenu} contentContainerStyle={s.standaloneMenu}><MenuSheet menu={menu}/></ScrollView></SafeAreaView>}
function MenuSheet({menu}){const Group=({course,title})=>{const items=menu.filter(x=>x.course===course);if(!items.length)return null;return <View style={s.printMenuSection}><Text style={s.printMenuTitle}>{title}</Text>{items.map((item,index)=><View key={item.id} style={s.printMenuItem}><Text style={s.printDishName}>{index+1}. {item.name}</Text><Text style={s.printDishDescription}>{item.description}</Text><Text style={s.printDishPrice}>R{item.price}</Text></View>)}</View>};return <><View style={s.printLogoRow}><View style={{flex:1}}/><Image source={LOGO} style={s.printLogo} resizeMode="contain"/></View><View style={s.printColumns}><View style={s.printColumn}><Group course="Main" title="Pizza"/><Group course="Starters" title="Starters"/></View><View style={s.printColumn}><Group course="Desserts" title="Dessert"/></View></View><Group course="Drinks" title="Drink"/><Image source={{uri:food.hero}} style={s.printPizzaImage}/><Text style={s.printThankYou}>THANK YOU FOR DINING{`\n`}WITH US!</Text><Text style={s.printPromise}>Our promise: Fresh ingredients, generous toppings and delicious food made with love.</Text><Text style={s.printNoteTitle}>PLEASE NOTE</Text><Text style={s.printNote}>Please inform our staff of any food allergies.{`\n`}Prices are in South African Rand (ZAR).</Text><Text style={s.printSlogan}>Good pizza brings people together!</Text></>}
function DishPreviewScreen({menu,go,logout,openEdit}){const [selected,setSelected]=useState(menu[0]||null);return <SafeAreaView style={s.safe}><Header section="Dish preview" logout={logout} onBack={()=>go('menuOptions')} onOptions={()=>go('menuOptions')} onSearch={()=>go('search')}/><ScrollView style={{backgroundColor:ORANGE}} contentContainerStyle={s.pagePad}><Text style={s.pageTitle}>Dish preview</Text><Text style={s.pageCopy}>Christofell, I’ll show you exactly how each dish appears before you publish it.</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.dishPicker}>{menu.map(dish=><Pressable key={dish.id} onPress={()=>setSelected(dish)} style={[s.dishPickerChip,selected?.id===dish.id&&s.dishPickerActive]}><Text style={[s.dishPickerText,selected?.id===dish.id&&{color:'#fff'}]}>{dish.name}</Text></Pressable>)}</ScrollView>{selected&&<View style={s.largeDishPreview}><Image source={{uri:selected.image}} style={s.largeDishImage}/><View style={s.largeDishBody}><Text style={s.previewCourse}>{selected.course.toUpperCase()}</Text><Text style={s.previewName}>{selected.name}</Text><Text style={s.previewPrice}>R {selected.price}</Text><Text style={s.previewDesc}>{selected.description}</Text><Text style={s.previewIngredients}><Text style={{fontWeight:'900'}}>Ingredients: </Text>{selected.ingredients}</Text><Pressable onPress={()=>openEdit(selected)} style={s.saveButton}><Text style={s.saveText}>EDIT THIS DISH</Text></Pressable></View></View>}</ScrollView></SafeAreaView>}
function Metric({value,label}){return <View style={s.metric}><Text style={s.metricValue}>{value}</Text><Text style={s.metricLabel}>{label}</Text></View>}
function Inventory({stock,setStock,go,logout}){const statuses=['In stock','Low stock','Out of stock'];const update=(id,key,value)=>setStock(items=>items.map(x=>x.id===id?{...x,[key]:value}:x));const toggleChecked=(item)=>setStock(items=>items.map(x=>x.id===item.id?{...x,checked:!x.checked,lastChecked:!x.checked?new Date().toLocaleDateString('en-ZA'):x.lastChecked}:x));const add=()=>setStock(items=>[...items,{id:Date.now().toString(),name:'New ingredient',qty:'0 units',status:'Out of stock',storage:'Choose storage',checked:false,lastChecked:'Not checked'}]);return <BluePage title="Inventory management" go={go} logout={logout}><View style={s.statusGrid}><StatusCard color="#31c900" value={stock.length} label="Total items"/><StatusCard color="#b40000" value={stock.filter(x=>x.status==='Low stock').length} label="Low stock"/><StatusCard color="#07165f" value={stock.filter(x=>x.status==='Out of stock').length} label="Out of stock"/><StatusCard color="#167b1f" value={stock.filter(x=>x.checked).length} label="Checked today"/></View><View style={s.sectionAction}><Text style={s.panelTitle}>Inventory checklist</Text><Pressable onPress={add} style={s.inlineAdd}><Text style={s.inlineAddText}>＋ ADD</Text></Pressable></View><View style={s.whitePanel}>{stock.map(item=><View key={item.id} style={s.inventoryCard}><View style={s.inventoryTopRow}><Pressable onPress={()=>toggleChecked(item)} style={[s.inventoryCheck,item.checked&&s.inventoryCheckDone]}><Text style={s.inventoryCheckMark}>{item.checked?'✓':''}</Text></Pressable><View style={{flex:1}}><TextInput value={item.name} onChangeText={v=>update(item.id,'name',v)} style={s.inlineName}/><TextInput value={item.qty} onChangeText={v=>update(item.id,'qty',v)} style={s.inlineValue}/></View><Pressable onPress={()=>update(item.id,'status',statuses[(statuses.indexOf(item.status)+1)%statuses.length])}><Text style={[s.statusPill,item.status==='In stock'?s.good:item.status==='Low stock'?s.warn:s.bad]}>{item.status}</Text></Pressable><Pressable onPress={()=>setStock(items=>items.filter(x=>x.id!==item.id))}><Text style={s.removeMark}>×</Text></Pressable></View><View style={s.inventoryMeta}><View style={s.storageField}><Text style={s.metaLabel}>STORED IN</Text><TextInput value={item.storage} onChangeText={v=>update(item.id,'storage',v)} style={s.storageInput}/></View><View style={s.lastChecked}><Text style={s.metaLabel}>LAST CHECKED</Text><Text style={s.lastCheckedValue}>{item.lastChecked}</Text></View></View></View>)}</View><Text style={s.editHint}>Tick items as they are reviewed. Names, quantities and storage locations can be edited directly.</Text></BluePage>}
function Orders({orders,setOrders,staff,go,logout}){const [newOrder,setNewOrder]=useState('');const statuses=['Pending','Preparing','Ready'];const chefs=staff.filter(x=>x.role.toLowerCase().includes('chef'));const availableChefs=chefs.length?chefs:staff;const update=(id,key,value)=>setOrders(items=>items.map(x=>x.id===id?{...x,[key]:value}:x));const add=()=>{if(!newOrder.trim())return;setOrders(items=>[...items,{id:Date.now().toString(),name:newOrder.trim(),status:'Pending',image:food.margherita,chefId:availableChefs[0]?.id||''}]);setNewOrder('');};return <BluePage title="Dish ordering system" go={go} logout={logout}><View style={s.chefLegend}><Text style={s.chefLegendTitle}>Chef colour key</Text><View style={s.chefLegendRow}>{availableChefs.map(chef=><View key={chef.id} style={s.chefLegendItem}><View style={[s.chefLegendDot,{backgroundColor:chef.color}]}/><Text style={s.chefLegendName}>{chef.name}</Text></View>)}</View></View><View style={s.quickAdd}><TextInput value={newOrder} onChangeText={setNewOrder} placeholder="Add a new kitchen order" style={s.quickAddInput}/><Pressable onPress={add} style={s.inlineAdd}><Text style={s.inlineAddText}>ADD</Text></Pressable></View>{statuses.map((title,i)=><View style={s.whitePanel} key={title}><Text style={s.panelTitle}>{title} orders</Text>{orders.filter(x=>x.status===title).map(item=>{const chef=availableChefs.find(x=>x.id===item.chefId)||availableChefs[0];const chefIndex=Math.max(0,availableChefs.findIndex(x=>x.id===item.chefId));return <View key={item.id} style={[s.orderAssignment,{borderLeftColor:chef?.color||'#777'}]}><View style={s.orderRow}><Image source={{uri:item.image}} style={s.orderImage}/><TextInput value={item.name} onChangeText={v=>update(item.id,'name',v)} style={s.orderEditName}/><Pressable onPress={()=>update(item.id,'status',statuses[(i+1)%statuses.length])}><Text style={[s.orderStatus,{backgroundColor:i===0?'#a90000':i===1?'#d6a900':'#16a626'}]}>{title} ›</Text></Pressable><Pressable onPress={()=>setOrders(items=>items.filter(x=>x.id!==item.id))}><Text style={s.removeMark}>×</Text></Pressable></View><View style={s.preparedByRow}><Text style={s.preparedByLabel}>{title==='Ready'?'PREPARED BY':'PREPARING CHEF'}</Text><Pressable onPress={()=>update(item.id,'chefId',availableChefs[(chefIndex+1)%availableChefs.length]?.id)} style={[s.chefAssignment,{backgroundColor:chef?.color||'#777'}]}>{chef?.image?<Image source={{uri:chef.image}} style={s.chefAssignmentPhoto}/>:<View style={s.chefAssignmentAvatar}><Text style={s.chefAssignmentInitial}>{chef?.name?.[0]||'?'}</Text></View>}<Text style={s.chefAssignmentName}>{chef?.name||'Unassigned'} ›</Text></Pressable></View></View>})}</View>)}<Text style={s.editHint}>Christofell, tap a chef’s coloured name to reassign the order, or tap its status to advance it.</Text></BluePage>}
function Analytics({expenses,setExpenses,go,logout}){const total=expenses.reduce((sum,x)=>sum+(Number(x.amount)||0),0);const max=Math.max(...expenses.map(x=>Number(x.amount)||0),1);const update=(id,key,value)=>setExpenses(items=>items.map(x=>x.id===id?{...x,[key]:value}:x));const add=()=>setExpenses(items=>[...items,{id:Date.now().toString(),name:'New expense',amount:'0'}]);return <BluePage title="Sales performance" go={go} logout={logout}><View style={s.metrics}><Metric value="R 2,379" label="Total revenue"/><Metric value="48" label="Total orders"/><Metric value={`R ${total.toLocaleString('en-ZA')}`} label="Total expenses"/></View><View style={s.whitePanel}><Text style={s.panelTitle}>Revenue by day</Text><View style={s.chart}>{[72,44,27,76].map((h,i)=><View key={i} style={s.barWrap}><View style={[s.bar,{height:h*2}]}/><Text style={s.barLabel}>{['MON','TUE','WED','THU'][i]}</Text></View>)}</View></View><View style={s.whitePanel}><Text style={s.panelTitle}>Top selling items</Text>{[['Margherita Pizza','23','R 2,070'],['BBQ Chicken Pizza','18','R 2,160'],['Berry Sparkler','16','R 720']].map(x=><View style={s.saleRow} key={x[0]}><Text style={{flex:1}}>{x[0]}</Text><Text>{x[1]}</Text><Text style={{width:90,textAlign:'right',fontWeight:'700'}}>{x[2]}</Text></View>)}</View><View style={s.expenseHeader}><View style={{flex:1}}><Text style={[s.panelTitle,{color:'#fff',marginBottom:2}]}>Top expenses</Text><Text style={s.bluePersonal}>Christofell, I’ll help you track where the restaurant is spending the most.</Text></View><Pressable onPress={add} style={s.inlineAdd}><Text style={s.inlineAddText}>＋ ADD</Text></Pressable></View><View style={s.whitePanel}>{[...expenses].sort((a,b)=>(Number(b.amount)||0)-(Number(a.amount)||0)).map(item=><View key={item.id} style={s.expenseRow}><View style={{flex:1}}><TextInput value={item.name} onChangeText={v=>update(item.id,'name',v)} style={s.expenseName}/><View style={s.expenseTrack}><View style={[s.expenseFill,{width:`${((Number(item.amount)||0)/max)*100}%`}]}/></View></View><Text style={s.expenseCurrency}>R</Text><TextInput value={item.amount} onChangeText={v=>update(item.id,'amount',v)} keyboardType="decimal-pad" style={s.expenseAmount}/><Pressable onPress={()=>setExpenses(items=>items.filter(x=>x.id!==item.id))}><Text style={s.removeMark}>×</Text></Pressable></View>)}<View style={s.expenseTotal}><Text style={s.expenseTotalLabel}>TOTAL EXPENSES</Text><Text style={s.expenseTotalValue}>R {total.toLocaleString('en-ZA')}</Text></View></View></BluePage>}
function StatusCard({color,value,label}){return <View style={[s.statusCard,{borderTopColor:color}]}><Text style={s.statusLabel}>{label}</Text><Text style={[s.statusValue,{color}]}>{value}</Text></View>}
function Recipes({recipes,setRecipes,go,logout}){const [editing,setEditing]=useState(null);const update=(id,key,value)=>setRecipes(items=>items.map(x=>x.id===id?{...x,[key]:value}:x));const add=()=>{const id=Date.now().toString();setRecipes(items=>[{id,name:'New recipe',time:'20 min',yieldText:'4 servings',image:food.margherita,notes:'Add preparation and plating notes.'},...items]);setEditing(id);};return <BluePage title="Recipe management" go={go} logout={logout}><Pressable onPress={add} style={s.pageAdd}><Text style={s.pageAddText}>＋ ADD RECIPE</Text></Pressable>{recipes.map(recipe=><View style={s.recipeCard} key={recipe.id}><Image source={{uri:recipe.image}} style={s.recipeImage}/><View style={s.recipeBody}>{editing===recipe.id?<><TextInput value={recipe.name} onChangeText={v=>update(recipe.id,'name',v)} style={s.editField}/><View style={s.editPair}><TextInput value={recipe.time} onChangeText={v=>update(recipe.id,'time',v)} style={[s.editField,{flex:1}]}/><TextInput value={recipe.yieldText} onChangeText={v=>update(recipe.id,'yieldText',v)} style={[s.editField,{flex:1}]}/></View><TextInput value={recipe.notes} onChangeText={v=>update(recipe.id,'notes',v)} style={[s.editField,s.editArea]} multiline/><View style={s.editActions}><Pressable onPress={()=>setRecipes(items=>items.filter(x=>x.id!==recipe.id))}><Text style={s.dangerAction}>DELETE</Text></Pressable><Pressable onPress={()=>setEditing(null)} style={s.doneButton}><Text style={s.doneText}>DONE</Text></Pressable></View></>:<><Text style={s.recipeName}>{recipe.name}</Text><Text style={s.muted}>{recipe.time} · {recipe.yieldText}</Text><Text style={s.recipeText}>{recipe.notes}</Text><Pressable onPress={()=>setEditing(recipe.id)} style={s.recipeButton}><Text style={s.recipeButtonText}>EDIT RECIPE</Text></Pressable></>}</View></View>)}</BluePage>}
function FoodCosts({menu,costs,setCosts,go,logout}){return <BluePage title="Food cost management" go={go} logout={logout}><Text style={s.blueCopy}>Edit each ingredient cost. Margins recalculate automatically against the menu price.</Text>{menu.map((dish,i)=>{const defaultCost=(Number(dish.price)*(i%2?0.32:0.28)).toFixed(2);const cost=costs[dish.id]??defaultCost;const margin=Number(dish.price)>0?(100-(Number(cost||0)/Number(dish.price)*100)).toFixed(0):0;return <View style={s.costRow} key={dish.id}><Image source={{uri:dish.image}} style={s.costImage}/><View style={{flex:1}}><Text style={s.stockName}>{dish.name}</Text><View style={s.costInputRow}><Text style={s.currency}>Cost R</Text><TextInput value={String(cost)} onChangeText={v=>setCosts(x=>({...x,[dish.id]:v}))} keyboardType="decimal-pad" style={s.costInput}/><Text style={s.muted}>Price R{dish.price}</Text></View></View><View style={s.marginPill}><Text style={s.marginValue}>{margin}%</Text><Text style={s.marginLabel}>margin</Text></View></View>})}</BluePage>}
function Staff({staff,setStaff,tasks,setTasks,go,logout}){const statuses=['Present','Late','Absent','Leave'];const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const palette=['#7c3aed','#0ea5e9','#f59e0b','#ec4899','#ef4444','#14b8a6','#84cc16','#f97316'];const [newTask,setNewTask]=useState('');const [newDay,setNewDay]=useState('Mon');const [newStaffId,setNewStaffId]=useState(staff[0]?.id||'');const update=(id,key,value)=>setStaff(items=>items.map(x=>x.id===id?{...x,[key]:value}:x));const updateTask=(id,key,value)=>setTasks(items=>items.map(x=>x.id===id?{...x,[key]:value}:x));const addStaff=()=>{const id=Date.now().toString();setStaff(items=>[...items,{id,name:'New staff member',role:'Role',status:'Present',color:palette[items.length%palette.length],image:`https://i.pravatar.cc/150?u=${id}`}]);setNewStaffId(id);};const removeStaff=(id)=>{setStaff(items=>items.filter(x=>x.id!==id));setTasks(items=>items.filter(x=>x.staffId!==id));if(newStaffId===id)setNewStaffId(staff.find(x=>x.id!==id)?.id||'');};const addTask=()=>{if(!newTask.trim()||!staff.length)return;setTasks(items=>[...items,{id:Date.now().toString(),title:newTask.trim(),staffId:newStaffId||staff[0].id,day:newDay,done:false}]);setNewTask('');};const personFor=id=>staff.find(x=>x.id===id)||staff[0];return <BluePage title="Staff management" go={go} logout={logout}><View style={s.sectionAction}><Text style={[s.panelTitle,{color:'#fff'}]}>Staff colour key</Text><Pressable onPress={addStaff} style={s.inlineAdd}><Text style={s.inlineAddText}>＋ ADD</Text></Pressable></View><View style={s.whitePanel}>{staff.map(person=><View style={s.staffRow} key={person.id}><Pressable onPress={()=>update(person.id,'color',palette[(palette.indexOf(person.color)+1)%palette.length])} style={[s.staffPhotoRing,{borderColor:person.color}]}><Image source={{uri:person.image}} style={s.staffPhoto}/></Pressable><View style={{flex:1}}><TextInput value={person.name} onChangeText={v=>update(person.id,'name',v)} style={s.inlineName}/><TextInput value={person.role} onChangeText={v=>update(person.id,'role',v)} style={s.inlineValue}/></View><Pressable onPress={()=>update(person.id,'status',statuses[(statuses.indexOf(person.status)+1)%statuses.length])}><Text style={[s.statusPill,person.status==='Present'?s.good:person.status==='Late'?s.warn:s.bad]}>{person.status}</Text></Pressable><Pressable onPress={()=>removeStaff(person.id)}><Text style={s.removeMark}>×</Text></Pressable></View>)}</View><Text style={s.editHint}>Each person has a unique colour. Tap their coloured circle to change it.</Text><View style={s.staffSectionHeader}><Text style={s.staffSectionTitle}>Weekly task planner</Text><Text style={s.staffSectionMeta}>{tasks.filter(x=>x.done).length}/{tasks.length} complete</Text></View><View style={s.calendarInput}><Text style={s.plannerLabel}>WHAT NEEDS TO BE DONE?</Text><TextInput value={newTask} onChangeText={setNewTask} placeholder="Type a new task" style={s.calendarTaskInput}/><Text style={s.plannerLabel}>CHOOSE A DAY</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.selectorScroll}>{days.map(day=><Pressable key={day} onPress={()=>setNewDay(day)} style={[s.daySelector,newDay===day&&s.daySelectorActive]}><Text style={[s.daySelectorText,newDay===day&&{color:'#fff'}]}>{day}</Text></Pressable>)}</ScrollView><Text style={s.plannerLabel}>ASSIGN TO A STAFF MEMBER</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.selectorScroll}>{staff.map(person=><Pressable key={person.id} onPress={()=>setNewStaffId(person.id)} style={[s.staffSelector,newStaffId===person.id&&{borderColor:person.color,backgroundColor:`${person.color}18`}]}><Image source={{uri:person.image}} style={[s.selectorPhoto,{borderColor:person.color}]}/><Text style={s.staffSelectorText}>{person.name}</Text></Pressable>)}</ScrollView><Pressable onPress={addTask} style={s.calendarAddButton}><Text style={s.calendarAddText}>ADD TO {newDay.toUpperCase()} CALENDAR</Text></Pressable></View><View style={s.whitePanel}>{tasks.map(task=>{const person=personFor(task.staffId);const staffIndex=Math.max(0,staff.findIndex(x=>x.id===task.staffId));return <View key={task.id} style={s.staffTask}><Pressable onPress={()=>updateTask(task.id,'done',!task.done)} style={[s.taskCheck,task.done&&{backgroundColor:person?.color,borderColor:person?.color}]}><Text style={s.inventoryCheckMark}>{task.done?'✓':''}</Text></Pressable><View style={{flex:1}}><TextInput value={task.title} onChangeText={v=>updateTask(task.id,'title',v)} style={[s.taskTitle,task.done&&s.taskDone]}/><View style={s.taskControls}><Pressable onPress={()=>updateTask(task.id,'staffId',staff[(staffIndex+1)%staff.length]?.id)} style={[s.assigneeChip,{backgroundColor:person?.color||'#777'}]}><Text style={s.assigneeText}>{person?.name||'Unassigned'}</Text></Pressable><Pressable onPress={()=>updateTask(task.id,'day',days[(days.indexOf(task.day)+1)%days.length])} style={s.dayChip}><Text style={s.dayChipText}>{task.day} ›</Text></Pressable></View></View><Pressable onPress={()=>setTasks(items=>items.filter(x=>x.id!==task.id))}><Text style={s.removeMark}>×</Text></Pressable></View>})}</View><Text style={s.editHint}>Edit task text directly. Tap a staff name or day to move an existing task.</Text><Text style={s.staffSectionTitle}>Weekly calendar</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.calendarScroll}><View style={s.calendarRow}>{days.map(day=><View key={day} style={s.calendarDay}><View style={s.calendarDayHeader}><Text style={s.calendarDayTitle}>{day}</Text><Pressable onPress={()=>setNewDay(day)}><Text style={s.calendarDayAdd}>＋</Text></Pressable></View>{tasks.filter(x=>x.day===day).map(task=>{const person=personFor(task.staffId);return <View key={task.id} style={[s.calendarTask,{borderLeftColor:person?.color||'#777',opacity:task.done?.55:1}]}><Text style={s.calendarTaskTitle} numberOfLines={2}>{task.title}</Text><View style={s.calendarPerson}>{person?.image?<Image source={{uri:person.image}} style={[s.calendarPhoto,{borderColor:person?.color||'#777'}]}/>:<View style={[s.calendarDot,{backgroundColor:person?.color||'#777'}]}/>}<Text style={s.calendarPersonText} numberOfLines={1}>{person?.name||'Unassigned'}</Text></View></View>})}</View>)}</View></ScrollView></BluePage>}
function Safety({checks,setChecks,allergy,setAllergy,go,logout}){const update=(id,key,value)=>setChecks(items=>items.map(x=>x.id===id?{...x,[key]:value}:x));const add=()=>setChecks(items=>[...items,{id:Date.now().toString(),label:'New safety check',done:false}]);return <BluePage title="Health and safety" go={go} logout={logout}><View style={s.safetyIntro}><Text style={s.safetyTitle}>Chef’s service checklist</Text><Text style={s.safetyText}>Tick completed checks and edit wording whenever procedures change.</Text></View><View style={s.whitePanel}>{checks.map(item=><View style={s.checkRow} key={item.id}><Pressable onPress={()=>update(item.id,'done',!item.done)} style={s.checkBox}><Text style={s.checkMark}>{item.done?'✓':''}</Text></Pressable><TextInput value={item.label} onChangeText={v=>update(item.id,'label',v)} style={s.checkInput}/><Pressable onPress={()=>setChecks(items=>items.filter(x=>x.id!==item.id))}><Text style={s.removeMark}>×</Text></Pressable></View>)}<Pressable onPress={add} style={s.addCheck}><Text style={s.addCheckText}>＋ ADD CHECK</Text></Pressable></View><View style={s.allergyCard}><Text style={[s.panelTitle,{color:'#fff'}]}>Allergy reminder</Text><TextInput value={allergy} onChangeText={setAllergy} multiline style={s.allergyInput}/></View></BluePage>}
function BluePage({title,go,logout,children}){const messages={'Inventory management':'Christofell, I’ll help you keep every ingredient checked, stored correctly and ready for service.','Dish ordering system':'Christofell, I’ve arranged your kitchen orders so you can move each dish through service.','Sales performance':'Christofell, I’ve summarised your sales so you can see what is working best.','Recipe management':'Christofell, I’ll keep your recipes organised and easy for your kitchen team to follow.','Food cost management':'Christofell, I’ll recalculate your margins whenever you change a dish cost.','Staff management':'Christofell, I’ve brought your team, tasks and weekly calendar together for you.','Health and safety':'Christofell, I’ll help you keep your safety checks clear and up to date.'};return <SafeAreaView style={s.safe}><Header section="Restaurant management" logout={logout} onBack={()=>go('restaurant')} onOptions={()=>go('restaurantOptions')} onSearch={()=>go('search')}/><ScrollView style={{backgroundColor:BLUE}} contentContainerStyle={s.bluePad}><Text style={s.blueTitle}>{title}</Text><Text style={s.bluePersonal}>{messages[title]||`Christofell, I’ve prepared this page for you.`}</Text>{children}</ScrollView></SafeAreaView>}
function Preview({data,close}){
  const MenuGroup=({course,title})=>{const items=data?.menu?.filter(x=>x.course===course)||[];if(!items.length)return null;return <View style={s.printMenuSection}><Text style={s.printMenuTitle}>{title}</Text>{items.map((item,index)=><View key={item.id} style={s.printMenuItem}><Text style={s.printDishName}>{index+1}. {item.name}</Text><Text style={s.printDishDescription}>{item.description}</Text><Text style={s.printDishPrice}>R{item.price}</Text></View>)}</View>};
  return <Modal visible={!!data} transparent animationType="fade" onRequestClose={close}><View style={s.overlay}><View style={[s.preview,data?.all&&s.fullMenuPreview]}>{data?.all?<ScrollView style={s.printMenu} contentContainerStyle={s.printMenuContent}><View style={s.printLogoRow}><View style={{flex:1}}/><Image source={LOGO} style={s.printLogo} resizeMode="contain"/></View><View style={s.printColumns}><View style={s.printColumn}><MenuGroup course="Main" title="Pizza"/><MenuGroup course="Starters" title="Starters"/></View><View style={s.printColumn}><MenuGroup course="Desserts" title="Dessert"/></View></View><MenuGroup course="Drinks" title="Drink"/><Image source={{uri:food.hero}} style={s.printPizzaImage}/><Text style={s.printThankYou}>THANK YOU FOR DINING{`\n`}WITH US!</Text><Text style={s.printPromise}>Our promise: Fresh ingredients, generous toppings and delicious food made with love.</Text><View style={s.printServiceList}><Text style={s.printSmall}>• Dine in</Text><Text style={s.printSmall}>• Takeaways</Text><Text style={s.printSmall}>• Collection orders</Text><Text style={s.printSmall}>• Delivery available</Text></View><Text style={s.printNoteTitle}>PLEASE NOTE</Text><Text style={s.printNote}>Please inform our staff of any food allergies.{`\n`}Prices are in South African Rand (ZAR). Menu prices are proposed example prices and may change.</Text><Text style={s.printSlogan}>Good pizza brings people together!</Text></ScrollView>:data&&<><Image source={{uri:data.image}} style={s.previewImage}/><View style={s.previewBody}><Text style={s.previewCourse}>{data.course}</Text><Text style={s.previewName}>{data.name}</Text><Text style={s.previewPrice}>R {data.price}</Text><Text style={s.previewDesc}>{data.description}</Text><Text style={s.previewIngredients}>{data.ingredients}</Text></View></>}<Pressable onPress={close} style={s.previewClose}><Text style={s.previewCloseText}>CLOSE PREVIEW</Text></Pressable></View></View></Modal>
}

const shadow={shadowColor:'#000',shadowOpacity:.2,shadowRadius:7,shadowOffset:{width:0,height:4},elevation:4};
